mapper.select:
SELECT muc.*, mu.nickname as userName, ci.coupon_name, ci.coupon_type
FROM member_user_coupon muc
LEFT JOIN coupon_info ci ON muc.coupon_id = ci.id
LEFT JOIN member_user mu ON muc.user_id = mu.id
WHERE muc.deleted = 0

    AND muc.coupon_id = #{reqVO.couponId}


    AND muc.order_id = #{reqVO.orderId}


    AND muc.order_no = #{reqVO.orderNo}


    AND mu.nickname LIKE CONCAT('%', #{reqVO.userName}, '%')

ORDER BY muc.id DESC

SELECT coupon_id as couponId, sum(numbers) as totalCount FROM member_user_coupon WHERE coupon_id IN
#{couponId}
GROUP BY coupon_id

SELECT ma.id, ma.type, ma.status, ma.start_time, ma.end_time, ma.scope, ma.available_num, ma.coupon_id, ma.author_id, ma.limited_num, ma.total_count, ci.coupon_name, ci.coupon_type, ci.threshold_amount, ci.discount_amount, ci.effective_type, ci.effective_days, ci.expiration_days, ci.max_issue_count, ci.issued_count, ci.used_count, muc.id AS user_coupon_id FROM member_user_coupon muc INNER JOIN coupon_info ci ON muc.coupon_id = ci.id INNER JOIN member_activity ma ON muc.coupon_id = ma.coupon_id
AND muc.user_id = #{userId} AND muc.deleted = 0 AND muc.status = 0 AND muc.expiration_time >= NOW() AND muc.effective_time <= NOW()
AND ma.type = #{activityType}
